import com.yjw.vultr.ServerLogin;
import com.yjw.vultr.ServerPower;
import org.json.JSONObject;
public class ServerLoginTest {
 static void check(boolean x){if(!x)throw new AssertionError("server login metadata");}
 public static void main(String[] args)throws Exception{
  JSONObject x=new JSONObject().put("os","Ubuntu 24.04 LTS x64").put("user_scheme","root").put("main_ip","203.0.113.42").put("default_password","HOST_ONLY").put("password","PROXY_ONLY");check(ServerLogin.username(x).equals("root"));check(ServerLogin.password(x).equals("HOST_ONLY"));check(ServerLogin.command(x).equals("ssh -p 22 root@203.0.113.42"));check(!ServerPower.safe(x).toString().contains("ONLY"));
  x.put("user_scheme","limited");check(ServerLogin.username(x).equals("linuxuser"));x.remove("default_password");check(ServerLogin.password(x).isEmpty());x.put("default_password",JSONObject.NULL);check(ServerLogin.password(x).isEmpty());x.remove("user_scheme");check(ServerLogin.username(x).isEmpty());x.put("username","custom-user");check(ServerLogin.username(x).equals("custom-user"));x.put("username","root;touch /tmp/injected");check(ServerLogin.command(x).isEmpty());x.put("username","root").put("main_ip","203.0.113.42;echo secret");check(ServerLogin.command(x).isEmpty());x.put("os","Windows Server 2025").put("user_scheme","root");x.remove("username");check(ServerLogin.username(x).isEmpty()&&ServerLogin.command(x).isEmpty());
  String one="11111111-1111-4111-8111-111111111111",two="22222222-2222-4222-8222-222222222222";JSONObject data=new JSONObject();JSONObject raw=new JSONObject().put("id",one).put("os","Ubuntu 24.04").put("user_scheme","root").put("default_password","ONE_HOST").put("password","PROXY_ONLY");ServerLogin.remember(data,raw,1000,false);raw.put("id",two).put("default_password","TWO_HOST");ServerLogin.remember(data,raw,1001,true);check(ServerLogin.password(ServerLogin.cached(data,one)).equals("ONE_HOST"));check(ServerLogin.password(ServerLogin.cached(data,two)).equals("TWO_HOST"));check(!data.toString().contains("PROXY_ONLY"));check(ServerLogin.fresh(ServerLogin.cached(data,one),300999));check(!ServerLogin.fresh(ServerLogin.cached(data,one),301000));raw.remove("default_password");ServerLogin.remember(data,raw,2000,false);check(ServerLogin.password(ServerLogin.cached(data,two)).equals("TWO_HOST"));raw.put("default_password","");ServerLogin.remember(data,raw,2000,false);check(ServerLogin.password(ServerLogin.cached(data,two)).equals("TWO_HOST"));ServerLogin.remember(data,raw,2001,true);check(ServerLogin.password(ServerLogin.cached(data,two)).equals("TWO_HOST"));ServerLogin.forget(data,one);check(ServerLogin.cached(data,one)==null&&ServerLogin.cached(data,two)!=null);
  JSONObject manualTarget=new JSONObject().put("id",one).put("os","Ubuntu 24.04").put("user_scheme","root").put("main_ip","203.0.113.42");ServerLogin.manual(data,manualTarget,"my-user","MANUAL_PASSWORD",3000);check(ServerLogin.username(ServerLogin.cached(data,one)).equals("my-user"));check(ServerLogin.fresh(ServerLogin.cached(data,one),999999999));ServerLogin.remember(data,new JSONObject(manualTarget.toString()).put("default_password","CLOUD_PASSWORD"),4000,true);check(ServerLogin.password(ServerLogin.cached(data,one)).equals("MANUAL_PASSWORD"));check(!ServerPower.safe(ServerLogin.cached(data,one)).toString().contains("MANUAL_PASSWORD"));
  JSONObject deploy=new JSONObject().put("id",two).put("os","Ubuntu 24.04 LTS x64").put("ip","203.0.113.22").put("ssh_username","vultr").put("ssh_password","TestOnlyPassw0rd123").put("phase","created");ServerLogin.initialized(data,deploy,5000);check(!ServerLogin.username(ServerLogin.cached(data,two)).equals("vultr"));deploy.put("phase","subscription-ready");ServerLogin.initialized(data,deploy,5001);check(ServerLogin.username(ServerLogin.cached(data,two)).equals("vultr"));check(ServerLogin.password(ServerLogin.cached(data,two)).equals("TestOnlyPassw0rd123"));check(ServerLogin.command(ServerLogin.cached(data,two)).equals("ssh -p 22 vultr@203.0.113.22"));ServerLogin.remember(data,new JSONObject(deploy.toString()).put("username","root").put("default_password","OLD_ROOT"),6000,true);check(ServerLogin.username(ServerLogin.cached(data,two)).equals("vultr"));check(ServerLogin.fresh(ServerLogin.cached(data,two),999999999));ServerLogin.manual(data,deploy,"edited","NEW",7000);ServerLogin.initialized(data,deploy,8000);check(ServerLogin.password(ServerLogin.cached(data,two)).equals("NEW"));
  System.out.println("PASS: API username/default password, no proxy-password fallback, public cache redaction and safe SSH command and separate per-instance credential cache");
 }
}
